   415	export function isProviderExecutionSurfaceCandidate(relativePath: string, source: string): boolean {
   416	  if (!relativePath.endsWith('.ts')) return false;
   417	  if (/(?:^|\/)(?:tasks|tests|generated)(?:\/|$)/.test(relativePath)) return false;
   418	  if (relativePath === 'core/provider-process-registry.ts') return false;
